3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Shared SHA-256 hex-digest helper for the identifiers derived on create. The member id's HASH8 segment (see
9	 * {@link IdentityKeyResolver#deriveMemberId}) and the household id (see
10	 * {@link HouseholdResolver#deriveHouseholdId}) are both a prefix of a SHA-256 digest, so both express the same hashing
11	 * in one place here. Kept a static utility like {@link LocalityResolver} and {@link MembershipLevelResolver}, since it
12	 * derives purely from its argument.
13	 */
14	public final class HexDigest {
15	
16	    private HexDigest() {
17	    }
18	
19	    /**
20	     * Returns the first {@code chars} upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of
21	     * {@code value}.
22	     *
23	     * @param value the value to hash
24	     * @param chars the number of leading hex characters to return
25	     * @return the leading upper-case hex characters of the digest
26	     */
27	    public static String upperHexPrefix(String value, int chars) {
28	        StringBuilder hex = new StringBuilder();
29	        for (byte b : digest(value)) {
30	            hex.append(String.format("%02X", b));
31	        }
32	        return hex.substring(0, chars);
33	    }
34	
35	    /**
36	     * Returns the full 64-character lower-case hex rendering of the SHA-256 digest of the UTF-8 bytes of {@code value}.
37	     * Used by the owner {@code identityKey} (see {@link IdentityKeyResolver#deriveIdentityKey}), which is expressed as
38	     * the whole digest rather than a leading prefix.
39	     *
40	     * @param value the value to hash
41	     * @return the 64-character lower-case hex digest
42	     */
43	    public static String lowerHex(String value) {
44	        StringBuilder hex = new StringBuilder();
45	        for (byte b : digest(value)) {
46	            hex.append(String.format("%02x", b));
47	        }
48	        return hex.toString();
49	    }
50	
51	    /**
52	     * Computes the raw SHA-256 digest of the UTF-8 bytes of {@code value}. Isolated here so every hex rendering shares
53	     * one notion of "the digest" (and one place that handles a missing SHA-256 provider) rather than repeating the
54	     * {@link MessageDigest} plumbing.
55	     *
56	     * @param value the value to hash
57	     * @return the SHA-256 digest bytes
58	     */
59	    private static byte[] digest(String value) {
60	        try {
61	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
62	        } catch (NoSuchAlgorithmException ex) {
63	            throw new IllegalStateException("SHA-256 is not available", ex);
64	        }
65	    }
66	}
