3	/**
4	 * Derives an owner's IANA {@code timezone} from its locality/region via the fixed region-to-timezone table
5	 * (NSW -> {@code Australia/Sydney}, VIC -> {@code Australia/Melbourne}, QLD -> {@code Australia/Brisbane}). The
6	 * locality is the region name resolved by {@link LocalityResolver#deriveLocality} from the owner's member id, so
7	 * this resolver simply looks that region up in {@link Region} and returns its timezone. {@code null} is returned when
8	 * the locality carries no known region (including {@link LocalityResolver#UNKNOWN}), which leaves the field absent.
9	 * Kept out of {@link OwnerMapper} so MapStruct does not mistake it for an implicit {@code String -> String} property
10	 * mapping method.
11	 */
12	public final class TimezoneResolver {
13	
14	    private TimezoneResolver() {
15	    }
16	
17	    /**
18	     * Returns the IANA timezone name for the given {@code memberId}, derived from the owner's locality/region.
19	     * Returns {@code null} when the member id carries no known region.
20	     *
21	     * @param memberId the owner's member id, may be {@code null}
22	     * @return the region's IANA timezone name, or {@code null} when the locality maps to no known region
23	     */
24	    public static String deriveTimezone(String memberId) {
25	        String locality = LocalityResolver.deriveLocality(memberId);
26	        for (Region region : Region.values()) {
27	            if (region.name().equals(locality)) {
28	                return region.getTimezone();
29	            }
30	        }
31	        return null;
32	    }
33	}
