package org.springframework.samples.petclinic.acceptance;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

/** TEMPORARY characterization test — pins V1 derived-field behavior across postcode/region
 *  scenarios so a behavior-preserving refactor can be verified. Deleted before finishing. */
class CharacterizationTest extends AcceptanceBase {

	private ObjectNode fixed(String lastName, String city, String postcode, String email) {
		ObjectNode o = om.createObjectNode();
		o.put("firstName", "Char");
		o.put("lastName", lastName);
		o.put("address", "1 Fixed Street");
		o.put("city", city);
		o.put("telephone", "0412345678");
		o.put("registrationDate", "2020-06-15");
		if (postcode != null) {
			o.put("postcode", postcode);
		}
		if (email != null) {
			o.put("email", email);
		}
		return o;
	}

	private void assertField(JsonNode n, String field, String expected) {
		if (expected == null) {
			assertThat(n.hasNonNull(field)).as(field + " should be null/absent").isFalse();
		}
		else {
			assertThat(n.get(field).asString()).as(field).isEqualTo(expected);
		}
	}

	@Test
	void derivedFieldsAreStable() throws Exception {
		JsonNode a = fetchOwner(createOwnerOk(fixed("Zeta", "Nowhere", null, null)));
		assertField(a, "memberId", "UNKNOWN20D1F0389B1");
		assertField(a, "householdId", null);
		assertField(a, "identityKey", "537cceaf0ccc5a8e878487562feced080a08b4983692ad0cd8ad5e12dec872b4");
		assertField(a, "locality", "UNKNOWN");
		assertField(a, "timezone", null);
		assertField(a, "ownerSegment", "PREMIUM_REGIONAL");
		assertThat(a.get("membershipLevel").asInt()).isEqualTo(3);

		JsonNode b = fetchOwner(createOwnerOk(fixed("Yankee", "Nowhere", "2000", null)));
		assertField(b, "memberId", "NSW2080BB37D14");
		assertField(b, "householdId", "640DACEB0556");
		assertField(b, "identityKey", "338acb5d59cc0642e65b9f1909522f1bf6b9bafbadc9d6f6b26de232013a2b87");
		assertField(b, "locality", "NSW");
		assertField(b, "timezone", "Australia/Sydney");
		assertField(b, "ownerSegment", "PREMIUM_METRO");

		JsonNode c = fetchOwner(createOwnerOk(fixed("Xray", "Sydney", "2000", "Foo.Bar@EXAMPLE.com")));
		assertField(c, "memberId", "NSW20FF6EF1EB0");
		assertField(c, "householdId", "02054EE15D55");
		assertField(c, "identityKey", "0db399d0409f06cf2fb0132ccf9425c01946ae6ef5be60839a252795ad8b2e4b");
		assertField(c, "locality", "NSW");
		assertField(c, "timezone", "Australia/Sydney");
		assertField(c, "ownerSegment", "PREMIUM_METRO");
		assertThat(c.get("membershipLevel").asInt()).isEqualTo(4);

		JsonNode d = fetchOwner(createOwnerOk(fixed("Whiskey", "Melbourne", "3000", null)));
		assertField(d, "memberId", "VIC205DEA35CD1");
		assertField(d, "householdId", "484C36F07931");
		assertField(d, "identityKey", "2544a086443ac3817bc770629ad4bffa9d833b49b49bd5811620365bbd66cdf3");
		assertField(d, "locality", "VIC");
		assertField(d, "timezone", "Australia/Melbourne");
		assertField(d, "ownerSegment", "PREMIUM_METRO");
	}

	@Test
	void auditEventShapeIsStable() throws Exception {
		try (AuditLogCapture audit = new AuditLogCapture()) {
			int id = createOwnerOk(fixed("Victor", "Sydney", "2000", null));
			JsonNode o = fetchOwner(id);
			String memberId = o.get("memberId").asString();
			// human-readable line
			assertThat(audit.anyContains("owner created: id=" + id, "memberId=" + memberId,
					"registrationDate=2020-06-15", "membershipLevel=")).isTrue();
			// structured JSON event
			assertThat(audit.anyContains("\"ownerId\":" + id, "\"memberId\":\"" + memberId + "\"",
					"\"membershipLevel\":", "\"event\":\"OWNER_CREATED\"", "\"seq\":")).isTrue();
		}
	}
}

